package cli

// Default flat tool surface for chat sessions: the composition-root adapter.
//
// The embedded Python reference manifest (tool_surface_flat.json, generated by
// go_hive/scripts/gen_tool_surface_flat.py) stays in this package because the
// generator writes it here; the projection itself (eager/lazy tiers, schema
// policy, grouped-module heuristic) lives in internal/cli/toolcatalog. The
// default set is the reference layers llm_request ∪ lifecycle ∪ synthetic from
// contracts/tool-definitions.json: 24 + 16 + 1 entries, 39 unique names.
//
// Execution routing is unchanged: a flat name runs through the same builtin,
// task, skills, colony or registry executor it always did. Python's three
// standalone playbook-control names are real catalogue definitions routed onto
// the playbook runner's status/stop actions (see session_tools.go).
//
// Parity: framework/tools/tool_tiers.py (eager vs searchable split)
// Parity: framework/agents/queen/queen_tools_defaults.py::always_enabled_tool_names
// Parity: framework/agent_loop/agent_loop.py (tools[] assembled per turn)

import (
	"context"
	_ "embed"
	"path/filepath"
	"strings"
	"sync"

	"github.com/shark2202/go_hive/go-hive/internal/cli/toolcatalog"
	"github.com/shark2202/go_hive/go-hive/internal/llm"
	"github.com/shark2202/go_hive/go-hive/internal/tools"
)

const (
	// ToolSurfaceEnvVar selects the model-visible chat tool surface.
	//   unset / "flat"  Python reference default set, flat names (default)
	//   "grouped"       the historical catalogue: grouped integration modules
	//                   (`airtable` + action) plus every other registered tool
	ToolSurfaceEnvVar = toolcatalog.SurfaceEnvVar
	// ToolSurfaceFlat is the default: one flat tool name per action.
	ToolSurfaceFlat = toolcatalog.SurfaceFlat
	// ToolSurfaceGrouped restores the grouped-module surface.
	ToolSurfaceGrouped = toolcatalog.SurfaceGrouped
)

//go:embed tool_surface_flat.json
var toolSurfaceFlatJSON []byte

var flatSurfaceOnce = sync.OnceValues(func() (*toolcatalog.Manifest, error) {
	return toolcatalog.ParseManifest(toolSurfaceFlatJSON)
})

// flatSurfaceTool is one default-set tool of the frozen Python reference.
type flatSurfaceTool = toolcatalog.FlatTool

// flatSurfaceManifest returns the embedded Python default surface. A malformed
// manifest is a check-in bug (the file is embedded and covered by tests), so it
// fails loudly instead of silently falling back to the grouped surface.
func flatSurfaceManifest() *toolcatalog.Manifest {
	doc, err := flatSurfaceOnce()
	if err != nil {
		panic(err)
	}
	return doc
}

// flatToolSurfaceEnabled reports whether the default flat surface is active.
func flatToolSurfaceEnabled() bool { return toolcatalog.FlatEnabled() }

// flatSurfaceDefaultNames returns the frozen default set in canonical order.
func flatSurfaceDefaultNames() []string { return flatSurfaceManifest().DefaultNames() }

// flatSurfaceStandaloneTools are default-set names this build advertises
// without a live catalogue definition (synthetic/loop-owned tools and the one
// Python-only name with no Go executor).
var flatSurfaceStandaloneTools = toolcatalog.StandaloneTools

// flatSurfaceColonyPhaseGated mirrors the server's colony-phase gate
// (server.ChatRuntime.toolsForTurn / colonyBoundQueenTool): these tools reach
// the model only once a colony runtime is bound. Kept here for the surface
// tests and the docs.
var flatSurfaceColonyPhaseGated = toolcatalog.ColonyPhaseGated

// flatSurfaceColonyPhaseOnly lists live definitions this build advertises in
// addition to the frozen default set, but only on the colony-bound surface.
var flatSurfaceColonyPhaseOnly = toolcatalog.ColonyPhaseOnly

// flatSurfacePlaybookActions maps the flat playbook-control names onto the
// actions the playbook runner serves.
var flatSurfacePlaybookActions = toolcatalog.PlaybookActions

// flatSurfaceKeepCurrentNames is the documented exception list of the flat
// projection: names that keep the live Go definition (the P1 parity manifest
// and lifecycle-only entries).
func flatSurfaceKeepCurrentNames() map[string]struct{} {
	parity := map[string]struct{}{}
	for name := range toolContractParityManifestData().Tools {
		parity[name] = struct{}{}
	}
	return flatSurfaceManifest().KeepCurrentNames(parity)
}

// flatSurfaceGroupedModule reports whether a live definition is a grouped
// integration module rather than a flat one-action tool.
func flatSurfaceGroupedModule(def llm.ToolDef) bool { return toolcatalog.GroupedModule(def) }

// EagerModelDefNames returns the always-on flat names this catalogue actually
// advertises, in the captured upstream order. The server's chat tool tier
// uses it as the first-request surface.
func (c *sessionToolCatalogue) EagerModelDefNames() []string {
	if c == nil || !flatToolSurfaceEnabled() {
		return nil
	}
	return flatSurfaceManifest().EagerModelDefNames(c.defs, flatSurfaceKeepCurrentNames())
}

// LazyModelDefs returns the definitions the lazy layer can load on demand
// (Python's searchable tier): the default-surface names not in the eager
// order — the lifecycle/colony layer — followed by the flat directory tools
// outside the default surface that this build can execute.
func (c *sessionToolCatalogue) LazyModelDefs() []llm.ToolDef {
	if c == nil || !flatToolSurfaceEnabled() {
		return nil
	}
	return flatSurfaceManifest().LazyModelDefs(c.defs, flatSurfaceKeepCurrentNames())
}

// LazySurfaceDeps is the loader-facing view of the flat lazy layer: the
// ordered always-on names and the deferred definitions, or nils when the
// grouped surface is selected (grouped mode keeps the pre-change surface).
func (c *sessionToolCatalogue) LazySurfaceDeps() (eager []string, deferred []llm.ToolDef) {
	if c == nil || !flatToolSurfaceEnabled() {
		return nil, nil
	}
	return c.EagerModelDefNames(), c.LazyModelDefs()
}

// ModelDefs returns the tool definitions a chat session advertises to the
// model. Flat mode (the default) advertises the Python reference default set;
// grouped mode returns the complete catalogue exactly as before.
func (c *sessionToolCatalogue) ModelDefs() []llm.ToolDef {
	if c == nil {
		return nil
	}
	if !flatToolSurfaceEnabled() {
		return c.defs
	}
	return c.flatModelDefs()
}

// flatModelDefs projects the catalogue onto the 39 default-set names.
func (c *sessionToolCatalogue) flatModelDefs() []llm.ToolDef {
	return flatSurfaceManifest().ModelDefs(c.defs, flatSurfaceKeepCurrentNames())
}

// executeFlatSurfaceTool routes a flat default-set call this build does not
// already handle by name. It runs only in flat mode: grouped mode keeps the
// pre-change routing (the names were never registered there).
func (c *sessionToolCatalogue) executeFlatSurfaceTool(ctx context.Context, name string, input map[string]any) (string, bool, bool) {
	if !flatToolSurfaceEnabled() {
		return "", false, false
	}
	switch name {
	case "search_tools":
		// The agent loop answers search_tools itself when the session has a
		// tool tier. Reaching the catalogue means there is no deferred surface
		// at all: answer with the inventory shape instead of an unknown tool.
		return tools.PythonJSONDumps(map[string]any{
			"status":      "ok",
			"loaded":      flatSurfaceDefaultNames(),
			"searchable":  []string{},
			"disabled":    []string{},
			"unavailable": []string{},
			"note": "This session advertises the Python reference default tool set as flat names; " +
				"no tools are deferred. Grouped integration tools are hidden by default and can be " +
				"enabled with HIVE_TOOL_SURFACE=grouped.",
		}), false, true
	case "sentinel_setup":
		// Queen-facing Sentinel setup (tokens / per-colony config / test /
		// detect_chat). Executes in-process against the same store, config
		// and credential store the desktop connector writes.
		return c.executeSentinelSetup(ctx, input)
	case "collect_result":
		// The agent loop answers collect_result from its background-tool
		// registry before dispatch ever reaches the catalogue. Reaching this
		// route means no loop is in the path (a direct catalogue call), so
		// answer with the loop-owned explanation instead of pretending the
		// tool does not exist.
		return tools.PythonJSONDumps(map[string]any{
			"error":   "loop_owned_tool",
			"tool":    name,
			"message": toolcatalog.NotImplementedMessage(name),
		}), true, true
	case "credentials":
		// The single CLI-style credentials tool. The chat runtime intercepts
		// it first so collect can park the loop; a direct catalogue call still
		// serves help/attach/detach against this session's Python-compatible
		// attachment root.
		sessionID := ""
		if strings.TrimSpace(c.root) != "" {
			sessionID = filepath.Base(c.root)
		}
		content, isError := tools.ExecuteCredentialsToolForSession(c.home.Root, sessionID, c.root, input)
		return content, isError, true
	case "suggest_colony":
		return tools.PythonJSONDumps(map[string]any{
			"error":   "not_implemented",
			"tool":    name,
			"message": toolcatalog.NotImplementedMessage(name),
		}), true, true
	}
	return "", false, false
}
